import { Hono } from "hono";
import { handleAgent } from "@/features/assistant/lib/handle-agent";

/** POST /api/chat. Mount with `app.route("/", chatApp)` or `chatApp.fetch(request)`. */
export const chatApp = new Hono().post("/api/chat", (c) =>
  handleAgent(c.req.raw)
);

docs:
Writes a Hono app at src/features/assistant/lib/chat-hono.ts. Also pulls the weather agent and handleAgent.

Mount with app.route("/", chatApp) or chatApp.fetch(request).

Then in src/features/assistant/lib/chat-transport.ts:

  import { DefaultChatTransport } from "ai";
  export const chatTransport = new DefaultChatTransport({ api: "/api/chat" });
  export const initialChatMessages = undefined;

Set AI_GATEWAY_API_KEY and optionally AI_MODEL.
